"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["80165"],{67881(e){e.exports=JSON.parse('{"id":"V4-208","slug":"secondaries-private-funds","term":"Secondaries (Private Funds)","also_known_as":[],"difficulty":"Advanced","definition":"Secondaries, in private markets, are transactions in which investors buy or sell existing interests in private equity, private credit or other private funds, or portfolios of fund investments, rather than committing to new funds.","explanation":["Investors in private funds usually commit money for about ten years or more, with few ways to exit early. The secondary market allows them to sell their interests before the fund ends, providing liquidity.","There are two main types. In investor-led or LP-led secondaries, an existing investor sells its stake in one or more funds to a secondary buyer. In manager-led or GP-led secondaries, the fund manager arranges a transaction, often moving one or more companies from an older fund into a new vehicle, called a continuation fund, giving existing investors the choice to sell or roll over their investment.","For example, a pension fund needing to rebalance its portfolio might sell its interests in several private equity funds to a secondary buyer, often at a discount to the funds\u2019 reported net asset value.","Buyers of secondaries can gain exposure to mature funds with known investments, shorter time to returns and often a purchase discount. The secondary market has grown rapidly, especially as slower company sales and listings increased investors\u2019 need for liquidity. Pricing depends on the quality of the assets and market conditions. Secondaries in this sense are different from the secondary market for publicly traded securities."],"note":"","total":1725,"prev":{"slug":"seasoned-equity-offering","term":"Seasoned Equity Offering"},"next":{"slug":"secondary-buyout","term":"Secondary Buyout"}}')}}]);